# --------------------------------------------------------------------------- #
# Retention policies and lineage-aware snapshot deletion
# --------------------------------------------------------------------------- #


RETENTION_POLICIES_PATH = (
    "/datasets/{dataset_name}/versions/{version}/retention-policies"
)


@app.post(
    RETENTION_POLICIES_PATH,
    response_model=RetentionPolicy,
    status_code=201,
)
def create_retention_policy(
